export interface DocumentComplianceCheck {
  rule: "residencyMatchesProperty" | "hostConfirmationMatchesLandlord" | "rentalAgreementMatchesLease" | "tenantIntakeMatchesProfile" | "propertyOwnershipMatchesClient" | "employmentMatchesEmployer" | "identityMatchesProfile" | "maritalStatusMatchesHousehold" | "birthRecordMatchesDependent" | "criminalBackgroundMatchesEligibility";
  outcome: "passed" | "failed" | "skipped";
  severity: "blocking" | "advisory";
  detail: string;
}

/** Cross-entity agreement. A blocking failure refuses verification outright; an advisory one is recorded and may be overridden by a reviewer who has looked at it. A context that cannot be loaded yields `skipped`, never `passed`. */
export interface DocumentComplianceReport {
  type: "identity" | "proofOfResidency" | "hostConfirmation" | "rentalAgreement" | "tenantIntake" | "propertyOwnership" | "employmentVerification" | "incomeProof" | "maritalStatus" | "birthRecord" | "criminalBackground" | "driverLicence" | "vehicleInsurance" | "roadworthiness" | "businessRegistration" | "taxClearance";
  rule?: "residencyMatchesProperty" | "hostConfirmationMatchesLandlord" | "rentalAgreementMatchesLease" | "tenantIntakeMatchesProfile" | "propertyOwnershipMatchesClient" | "employmentMatchesEmployer" | "identityMatchesProfile" | "maritalStatusMatchesHousehold" | "birthRecordMatchesDependent" | "criminalBackgroundMatchesEligibility" | Record<string, unknown>;
  checks: DocumentComplianceCheck[];
  passed: number;
  failed: number;
  skipped: number;
  blocking?: DocumentComplianceCheck[];
  /** True when nothing blocking failed — the document may be verified. */
  clear: boolean;
  score: number;
}

/** The document's clock. Notices fire on an exact rung (90/60/30/14/7/1 days) rather than continuously, so a holder gets four reminders over three months instead of ninety. */
export interface DocumentExpiryInfo {
  type: "identity" | "proofOfResidency" | "hostConfirmation" | "rentalAgreement" | "tenantIntake" | "propertyOwnership" | "employmentVerification" | "incomeProof" | "maritalStatus" | "birthRecord" | "criminalBackground" | "driverLicence" | "vehicleInsurance" | "roadworthiness" | "businessRegistration" | "taxClearance";
  expiresOn?: string | Record<string, unknown>;
  daysRemaining?: number | Record<string, unknown>;
  state: "noExpiry" | "valid" | "expiringSoon" | "expiresToday" | "expired";
  expired: boolean;
  noticeDue?: number | Record<string, unknown>;
  escalation: "none" | "notifyHolder" | "notifyCoordinator" | "notifyBackOffice" | "suspendPrivilege";
  requiresReverification: boolean;
  daysExpired?: number | Record<string, unknown>;
}

/** The type-specific field bag. Which keys are required is declared per type in `documentRules.ts` and published on `DocumentTypeRule`. */
export type DocumentFields = Record<string, string | number | boolean | string>;

/** What a client may submit. `status`, `desk`, `version`, `reference` and the audit trail are all server-controlled and absent here. */
export interface DocumentInput {
  type: "identity" | "proofOfResidency" | "hostConfirmation" | "rentalAgreement" | "tenantIntake" | "propertyOwnership" | "employmentVerification" | "incomeProof" | "maritalStatus" | "birthRecord" | "criminalBackground" | "driverLicence" | "vehicleInsurance" | "roadworthiness" | "businessRegistration" | "taxClearance";
  title?: string;
  subjectKind?: string;
  subject?: string;
  fields: DocumentFields;
  mimeType?: "application/pdf" | "image/jpeg" | "image/png" | "image/heic" | "image/webp";
  fileSize?: number;
  pageCount?: number;
  ocrConfidence?: number;
  resolution?: number;
  storageKey?: string;
}

/** The result of a lifecycle transition: the document as it now stands, what moved, and the trail summary. An illegal move never reaches this shape — it is a 409. */
export interface DocumentLifecycle {
  document: Document;
  transition: {
    from: "submitted" | "underReview" | "needsMoreInfo" | "verified" | "rejected" | "expired";
    to: "submitted" | "underReview" | "needsMoreInfo" | "verified" | "rejected" | "expired";
    action: "create" | "submit" | "review" | "requestInfo" | "verify" | "reject" | "expire" | "reverify" | "amend" | "archive";
    at: string;
    actor: string;
    reason?: string | Record<string, unknown>;
    requirements?: TransitionRequirements;
  };
  audit: DocumentAuditSummary;
}

/** Request variant of `DocumentLifecycle` — server-controlled fields removed. */
export interface DocumentLifecycleInput {
  document: Document;
  transition: {
    from: "submitted" | "underReview" | "needsMoreInfo" | "verified" | "rejected" | "expired";
    to: "submitted" | "underReview" | "needsMoreInfo" | "verified" | "rejected" | "expired";
    action: "create" | "submit" | "review" | "requestInfo" | "verify" | "reject" | "expire" | "reverify" | "amend" | "archive";
    at: string;
    actor: string;
    reason?: string | Record<string, unknown>;
    requirements?: TransitionRequirements;
  };
  audit: DocumentAuditSummary;
}

export type DocumentList = Document[];

/** Request variant of `DocumentList`. */
export type DocumentListInput = Document[];

/** An amendment. `type` is absent deliberately: retyping a document would change which fields are required, which compliance rule applies and how long it lives. A different type is a different document. */
export interface DocumentPatch {
  title?: string;
  subjectKind?: string;
  subject?: string;
  fields?: DocumentFields;
  mimeType?: "application/pdf" | "image/jpeg" | "image/png" | "image/heic" | "image/webp";
  fileSize?: number;
  pageCount?: number;
  ocrConfidence?: number;
  resolution?: number;
  storageKey?: string;
}

/** Four independent dimensions, weighted into one. Kept separate because a reviewer needs to know *which* is low: 62 for blur needs a re-upload, 62 for a name mismatch needs a conversation. */
export interface DocumentScore {
  completeness: number;
  clarity: number;
  consistency: number;
  crossDocument: number;
  overall: number;
  band: "poor" | "fair" | "good" | "excellent";
  /** False refuses verification however willing the reviewer. */
  meetsVerificationFloor?: boolean;
  weakest?: "completeness" | "clarity" | "consistency" | "crossDocument";
  scoredAt?: string;
}

/** Lifecycle, score, compliance and expiry in one read. A reviewer deciding whether to verify needs all four, and four round trips to assemble them is four chances to act on a stale one. */
export interface DocumentVerificationSummary {
  documentId: string;
  reference?: string;
  type: "identity" | "proofOfResidency" | "hostConfirmation" | "rentalAgreement" | "tenantIntake" | "propertyOwnership" | "employmentVerification" | "incomeProof" | "maritalStatus" | "birthRecord" | "criminalBackground" | "driverLicence" | "vehicleInsurance" | "roadworthiness" | "businessRegistration" | "taxClearance";
  lifecycle: {
    status: "submitted" | "underReview" | "needsMoreInfo" | "verified" | "rejected" | "expired";
    submittedAt?: string | Record<string, unknown>;
    reviewStartedAt?: string | Record<string, unknown>;
    verifiedAt?: string | Record<string, unknown>;
    rejectedAt?: string | Record<string, unknown>;
    expiredAt?: string | Record<string, unknown>;
    reviewable: boolean;
    desk?: "backOffice" | "coordinator" | "hqExecutive";
  };
  score: DocumentScore;
  compliance: DocumentComplianceReport;
  expiry: DocumentExpiryInfo;
  audit?: DocumentAudit[];
  auditSummary?: DocumentAuditSummary;
  /** The AND of reviewable, compliance-clear, above the score floor and not expired. */
  verifiable: boolean;
}

/** Request variant of `DocumentVerificationSummary` — server-controlled fields removed. */
export interface DocumentVerificationSummaryInput {
  documentId: string;
  reference?: string;
  type: "identity" | "proofOfResidency" | "hostConfirmation" | "rentalAgreement" | "tenantIntake" | "propertyOwnership" | "employmentVerification" | "incomeProof" | "maritalStatus" | "birthRecord" | "criminalBackground" | "driverLicence" | "vehicleInsurance" | "roadworthiness" | "businessRegistration" | "taxClearance";
  lifecycle: {
    status: "submitted" | "underReview" | "needsMoreInfo" | "verified" | "rejected" | "expired";
    submittedAt?: string | Record<string, unknown>;
    reviewStartedAt?: string | Record<string, unknown>;
    verifiedAt?: string | Record<string, unknown>;
    rejectedAt?: string | Record<string, unknown>;
    expiredAt?: string | Record<string, unknown>;
    reviewable: boolean;
    desk?: "backOffice" | "coordinator" | "hqExecutive";
  };
  score: DocumentScore;
  compliance: DocumentComplianceReport;
  expiry: DocumentExpiryInfo;
  audit?: DocumentAuditInput[];
  auditSummary?: DocumentAuditSummary;
  /** The AND of reviewable, compliance-clear, above the score floor and not expired. */
  verifiable: boolean;
}

